const cl = ($('Read Claim (Airtable Clusters)').first().json.records || [])[0];
if (!cl) throw new Error('Cluster not found: ' + $('Store Settings').first().json.cluster_id);
const posts = ($input.first().json.records || []).map(r => r.fields);
const lines = posts.map(p => JSON.stringify({ title: p.title, summary: p.summary, source: p.source, links_to: p.linked_url || null, posted: String(p.published_at || '').slice(0, 10) || null })).join('\n');
return [{ json: { record_id: cl.id, title: cl.fields.title || '', posts_text: lines,
  linked_urls: [...new Set(posts.map(p => p.linked_url).filter(Boolean))],
  post_urls: posts.map(p => p.url).filter(Boolean) } }];

const s = $('Store Settings').first().json;
const ci = $('Build Claim Input').first().json;
const platforms = s.platform_domains;
const host = (u) => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].replace(/^www\./, '').toLowerCase() : ''; };
const isPlatform = (h) => !h || platforms.some(p => h === p || h.endsWith('.' + p));
const seen = new Map();
const add = (url, found_by, gdate) => {
  if (!url || !/^https?:/i.test(url)) return;
  const clean = url.split('#')[0];
  const h = host(clean);
  if (isPlatform(h)) return;
  if (seen.has(clean)) { const c = seen.get(clean); if (c.found_by !== found_by && c.found_by !== 'post') c.found_by = 'both'; if (!c.gdate && gdate) c.gdate = gdate; return; }
  seen.set(clean, { url: clean, domain: h, found_by, gdate: gdate || '' });
};
ci.linked_urls.forEach(u => add(u, 'post'));
// Serper answers all queries in one call, one item per query: first the recent ones (date limit), then the same without a limit.
const items = $('Search Google (Serper)').all().map(i => i.json);
const hits = (part) => part.flatMap(j => (j.organic || []).map(r => ({ link: r.link, date: r.date || '' })));
hits(items.slice(0, items.length / 2)).forEach(r => add(r.link, 'serper', r.date));
const serper = hits(items.slice(items.length / 2));
const vjson = $('Search Web (Venice)').first().json || {};
const vcites = ((vjson.venice_parameters || {}).web_search_citations || []).map(c => c.url);
const vtext = (((vjson.choices || [])[0] || {}).message || {}).content || '';
const vurls = vcites.concat(vtext.match(/https?:\/\/[^\s)\]>"']+/g) || []).map(u => u.replace(/[.,;]+$/, ''));
for (let i = 0; i < Math.max(serper.length, vurls.length); i++) { if (serper[i]) add(serper[i].link, 'serper', serper[i].date); add(vurls[i], 'venice'); }
const list = [...seen.values()].slice(0, s.max_candidates);
return [{ json: { candidates: list, count: list.length } }];

const claim = $('State The Claim (via Ask Venice)').first().json.output;
const pages = $input.all().map(i => i.json).filter(p => p && p.url);
const words = [...new Set((claim.claim + ' ' + claim.about).toLowerCase().match(/[a-z0-9][a-z0-9.\-]{2,}/g) || [])];
const windowOf = (t) => {
  if (t.length <= 2500) return t;
  const low = t.toLowerCase(); let best = 0, bestScore = -1;
  for (let s = 0; s < low.length - 2500; s += 500) {
    const w = low.slice(s, s + 2500); const sc = words.reduce((a, k) => a + (w.includes(k) ? 1 : 0), 0);
    if (sc > bestScore) { bestScore = sc; best = s; }
  }
  return t.slice(best, best + 2500);
};
const readable = pages.filter(p => p.read_status === 'read').map((p, k) => ({ ...p, n: k + 1, excerpt_in: windowOf(p.text) }));
const esc = (s) => String(s).replace(/</g, '(').replace(/>/g, ')');
const pages_text = readable.map(p => `<page n="${p.n}" url="${p.url}">${esc(p.excerpt_in)}</page>`).join('\n');
return [{ json: { readable: readable.map(({ text, ...r }) => r), unreadable: pages.filter(p => p.read_status !== 'read').map(({ text, ...r }) => r),
  pages_text, readable_count: readable.length } }];

const s = $('Store Settings').first().json;
const claim = $('State The Claim (via Ask Venice)').first().json.output;
const ji = $('Build Judge Input').first().json;
const verdicts = $('Judge Stance And Tier (via Ask Venice)').isExecuted ? (($('Judge Stance And Tier (via Ask Venice)').first().json.output || {}).verdicts || []) : [];
if (ji.readable_count > 0 && verdicts.length === 0) throw new Error('Judge returned no verdicts for ' + ji.readable_count + ' readable pages');
const byN = Object.fromEntries(verdicts.map(v => [v.n, v]));
// recent = published in the last recent_days (7 for a daily run, 30 for a weekly run); older pages are background.
const since = new Date(Date.now() - (Number(s.recent_days) || 7) * 864e5).toISOString().slice(0, 10);
const whenOf = (d) => !d ? 'unknown' : (d >= since ? 'recent' : 'background');
// registrable domain: last two labels, or three for known second-level suffixes
const SL = ['co.uk', 'com.au', 'co.jp', 'com.br', 'co.in', 'org.uk', 'ac.uk', 'gov.uk', 'com.cn'];
const reg = (h) => { const p = h.split('.'); const last2 = p.slice(-2).join('.'); return SL.includes(last2) ? p.slice(-3).join('.') : last2; };
const evidence = [
  ...ji.readable.map(p => { const v = byN[p.n] || { stance: 'mentions', tier: 'other', excerpt: '', reason: 'no verdict' };
    return { url: p.url, domain: reg(p.domain), tier: v.tier, stance: v.stance, read_status: 'read', found_by: p.found_by, published: p.published || '', when: whenOf(p.published), excerpt: String(v.excerpt || '').slice(0, 400) }; }),
  ...ji.unreadable.map(p => ({ url: p.url, domain: reg(p.domain || ''), tier: '', stance: '', read_status: p.read_status, found_by: p.found_by, published: p.published || '', when: whenOf(p.published), excerpt: '' })),
];
const trusted = (e) => e.tier === 'official' || e.tier === 'reliable';
const sup = evidence.filter(e => e.stance === 'supports');
const supDomains = [...new Set(sup.map(e => e.domain))];
const trustedSupDomains = [...new Set(sup.filter(trusted).map(e => e.domain))];
const contra = evidence.filter(e => e.stance === 'contradicts' && trusted(e));
let label, reason;
if (!claim.checkable) { label = 'Opinion'; reason = 'A view, not a checkable fact.'; }
else if (contra.length) { label = 'Disputed'; reason = `Contradicted by ${[...new Set(contra.map(e => e.domain))].join(', ')}.`; }
else if (supDomains.length >= 2 && trustedSupDomains.length >= 1) { label = 'Corroborated'; reason = `Supported by ${supDomains.length} independent domains: ${supDomains.join(', ')}.`; }
else if (trustedSupDomains.length === 1) { label = 'Single source'; reason = `Only ${trustedSupDomains[0]} has stated it so far.`; }
else { label = 'Unverified'; reason = sup.length ? 'Only low-tier sources support it.' : (ji.readable_count ? 'No readable source supports it.' : 'No source could be read.'); }
const blocked = evidence.filter(e => e.read_status === 'blocked').length;
if (blocked) reason += ` ${blocked} page(s) could not be read.`;
// What the explainer writer reads: the claim, its label, the posts and every judged page with its tier and stance.
const esc = (t) => String(t).replace(/</g, '(').replace(/>/g, ')');
const pagesForWriter = ji.readable.map(p => { const v = byN[p.n] || {};
  return `<page n="${p.n}" url="${p.url}" tier="${v.tier || 'other'}" stance="${v.stance || 'mentions'}" date="${p.published || 'unknown'}" when="${whenOf(p.published)}">${esc(p.excerpt_in)}</page>`; }).join('\n');
const writer_input = `<claim>${esc(claim.claim)}</claim>\n<about>${esc(claim.about)}</about>\n<label>${label}</label>\n<label_reason>${esc(reason)}</label_reason>\n<posts>\n${$('Build Claim Input').first().json.posts_text}\n</posts>\n<pages>\n${pagesForWriter || '(no readable page)'}\n</pages>`;
return [{ json: { writer_input, record_id: $('Build Claim Input').first().json.record_id, label, reason,
  independent_domains: supDomains.length,
  official_links: sup.filter(e => e.tier === 'official').map(e => e.url).join('\n'),
  supporting_links: sup.filter(e => e.tier !== 'official').map(e => e.url).join('\n'),
  evidence: JSON.stringify(evidence), claim: claim.claim } }];

const a = $('Prepare Verify Save').first().json;
// label and status for WF3's loop; the rest is what WF3 saves to the story archive.
return [{ json: { cluster_id: $('Store Settings').first().json.cluster_id, label: a.label, independent_domains: a.independent_domains, status: 'ok', reason: a.reason,
  claim: a.claim, explainer: a.explainer, explainer_text: a.explainer_text, search_terms: a.search_terms,
  official_links: a.official_links, supporting_links: a.supporting_links, contradicting_links: a.contradicting_links, evidence: a.evidence } }];

// Joins the label result and the explainer, and writes the explainer as readable text for Airtable.
const a = $('Assign Label').first().json;
const x = $('Write Explainer (via Ask Venice)').first().json.output;
const ev = JSON.parse(a.evidence || '[]');
const STATUS = { confirmed: 'Confirmed', stated_only: 'Stated by the source only', not_disclosed: 'Not disclosed', contradicted: 'Contradicted' };
const lines = ['What happened: ' + x.what_happened];
if ((x.status_points || []).length) {
  lines.push('', 'Confirmed and not confirmed:');
  for (const p of x.status_points) lines.push('- ' + (STATUS[p.status] || p.status) + ': ' + p.point + (p.source ? ' (' + p.source + ')' : ''));
}
if (a.label === 'Disputed' && (x.two_sides.side_a || x.two_sides.side_b)) lines.push('', 'One side: ' + x.two_sides.side_a, 'Other side: ' + x.two_sides.side_b);
lines.push('', 'Why it matters: ' + x.why_it_matters, '', 'Open question: ' + x.open_question);
return [{ json: { ...a,
  contradicting_links: [...new Set(ev.filter(e => e.stance === 'contradicts').map(e => e.url))].join('\n'),
  explainer: x, explainer_text: lines.join('\n'),
  search_terms: (x.search_terms || []).map(t => String(t).trim()).filter(Boolean).slice(0, 8).join(', ') } }];
